def median(nums):
    """Median of nums as a float; 0.0 for an empty list."""
    s = sorted(nums)
    n = len(s)
    if n == 0:
        return 0.0
    if n % 2 == 1:
        return float(s[n // 2])
    return (s[n // 2 - 1] + s[n // 2]) / 2

